// Built-in masking functions
export const masks = {
  /**
   * Mask email address
   * Example: paul@example.com -> p***@e******.com
   */
  email: (v: string): string => {
    if (!v || !v.includes('@')) return v;
    const [local, domain] = v.split('@');
    if (!local || !domain) return v;
    const domainParts = domain.split('.');
    if (domainParts.length === 0) return v;
    const tld = domainParts.pop();
    const domainBase = domainParts.join('.');
    if (!domainBase || !tld) return v;
    return `${local[0]}${'*'.repeat(Math.max(local.length - 1, 1))}@${domainBase[0]}${'*'.repeat(Math.max(domainBase.length - 1, 1))}.${tld}`;
  },

  /**
   * Mask phone number
   * Example: 555-123-4567 -> ******4567
   */
  phone: (v: string): string => {
    if (!v) return v;
    const digits = v.replace(/\D/g, '');
    if (digits.length < 4) return v;
    return `${'*'.repeat(digits.length - 4)}${digits.slice(-4)}`;
  },

  /**
   * Mask SSN (Social Security Number)
   * Example: 123-45-6789 -> *****6789
   */
  ssn: (v: string): string => {
    if (!v) return v;
    const cleaned = v.replace(/\D/g, '');
    if (cleaned.length < 4) return v;
    return `${'*'.repeat(cleaned.length - 4)}${cleaned.slice(-4)}`;
  },

  /**
   * Mask credit card number
   * Example: 4111111111111234 -> ************1234
   */
  creditCard: (v: string): string => {
    if (!v) return v;
    const cleaned = v.replace(/\D/g, '');
    if (cleaned.length < 4) return v;
    return `${'*'.repeat(cleaned.length - 4)}${cleaned.slice(-4)}`;
  },

  /**
   * Mask name (each word)
   * Example: John Doe -> J*** D**
   */
  name: (v: string): string => {
    if (!v) return v;
    return v.split(' ').map(n => n.length > 0 ? `${n[0]}${'*'.repeat(Math.max(n.length - 1, 1))}` : n).join(' ');
  },

  /**
   * Completely redact the value
   * Example: any value -> [REDACTED]
   */
  redact: (_v: string): string => '[REDACTED]',
};

/**
 * Record-state masking: true when every `show.or.record` condition holds on
 * the row. Serialized from the compiler's canonical implementation — the
 * realtime Broadcaster inlines the same text.
 */
export const maskRecordHolds: (record: Record<string, unknown>, conditions: Record<string, Record<string, unknown>>) => boolean = function maskRecordHolds(record, conditions) {
  if (!record || typeof record !== "object")
    return !1;
  const fields = Object.keys(conditions);
  if (fields.length === 0)
    return !1;
  for (const field of fields) {
    if (!Object.prototype.hasOwnProperty.call(record, field))
      return !1;
    const value = record[field], cond = conditions[field];
    if (!cond || typeof cond !== "object")
      return !1;
    const ops = Object.keys(cond);
    if (ops.length !== 1)
      return !1;
    const op = ops[0], operand = cond[op];
    if (op === "null") {
      if (value != null)
        return !1;
    } else if (op === "notNull") {
      if (value == null)
        return !1;
    } else if (op === "equals") {
      if (value == null || value !== operand)
        return !1;
    } else if (op === "notEquals") {
      if (value == null || value === operand)
        return !1;
    } else if (op === "in") {
      if (value == null || !Array.isArray(operand) || !operand.includes(value))
        return !1;
    } else if (op === "notIn") {
      if (value == null || !Array.isArray(operand) || operand.includes(value))
        return !1;
    } else if (op === "before" || op === "after") {
      if (value == null || operand !== "now")
        return !1;
      const at = value instanceof Date ? value.getTime() : typeof value === "number" ? value : typeof value === "string" ? Date.parse(value) : Number.NaN;
      if (!Number.isFinite(at))
        return !1;
      const now = Date.now();
      if (op === "before" ? !(at < now) : !(at > now))
        return !1;
    } else
      return !1;
  }
  return !0;
};

